function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function formatDate(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat("en", { dateStyle: "medium", timeStyle: "short", timeZone: "UTC" }).format(date);
}

function formatMoney(minor, currency = "USD") {
  return new Intl.NumberFormat("en", { style: "currency", currency }).format(Number(minor || 0) / 100);
}

function safeUrl(value) {
  try {
    const url = new URL(String(value || ""));
    return ["http:", "https:"].includes(url.protocol) ? url.toString() : "#";
  } catch {
    return "#";
  }
}

function statusLabel(value) {
  return String(value || "unknown").replaceAll("_", " ");
}

function statusBadge(value) {
  return `<span class="status status-${escapeHtml(value)}">${escapeHtml(statusLabel(value))}</span>`;
}

function errorsBlock(errors = []) {
  return errors.length ? `<div class="alert alert-error" role="alert"><ul>${errors.map((error) => `<li>${escapeHtml(error)}</li>`).join("")}</ul></div>` : "";
}

function notice(message) {
  return message ? `<div class="alert alert-success" role="status">${escapeHtml(message)}</div>` : "";
}

function layout({ title, body, user = null }) {
  const brand = `<span class="brand-sign" aria-hidden="true"><span>Y</span><i></i></span><span class="brand-name"><span>YardSale</span><small>Cloud</small></span>`;
  const nav = user
    ? `<a class="brand" href="/dashboard">${brand}</a><nav class="site-nav" aria-label="Primary"><a href="/marketplace">Browse sales</a><a href="/dashboard">Dashboard</a>${user.is_admin ? `<a href="/admin">Admin</a>` : ""}<form method="post" action="/logout" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(user.csrfToken)}"><button class="nav-button" type="submit">Sign out</button></form></nav>`
    : `<a class="brand" href="/">${brand}</a><nav class="site-nav" aria-label="Primary"><a href="/marketplace">Browse sales</a><a href="/login">Sign in</a><a class="nav-cta" href="/signup">Create a store</a></nav>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Managed YardSale storefronts for local sellers"><title>${escapeHtml(title)} · YardSale Cloud</title><link rel="stylesheet" href="/styles.css?v=20260909-3"></head><body><a class="skip-link" href="#main-content">Skip to content</a><header class="site-header"><div class="container header-inner">${nav}</div></header><main id="main-content" class="container">${body}</main><footer class="site-footer"><div class="container footer-inner"><p>A small online corner for the things you’re ready to pass on.</p><p><a href="/legal/terms">Terms</a> · <a href="/legal/privacy">Privacy</a> · <a href="/legal/acceptable-use">Acceptable use</a> · <a href="/legal/prohibited-items">Prohibited items</a> · <a href="/legal/abuse">Report abuse</a></p></div></footer></body></html>`;
}

export function landingPage({ policy = { default_free_days: 14, default_paid_days: 30, default_store_price_minor: 500 } } = {}) {
  const freeDays = Number.isFinite(Number(policy.default_free_days)) ? Number(policy.default_free_days) : 14;
  const paidDays = Number.isFinite(Number(policy.default_paid_days)) ? Number(policy.default_paid_days) : 30;
  const priceMinor = Number.isFinite(Number(policy.default_store_price_minor)) ? Number(policy.default_store_price_minor) : 500;
  const body = `<section class="landing-page"><div class="hero-composition"><div class="hero-sign-column"><article class="hero-sign" aria-labelledby="hero-heading"><span class="sign-tape sign-tape-left" aria-hidden="true"></span><span class="sign-tape sign-tape-right" aria-hidden="true"></span><div class="sign-surface"><p class="marker-kicker">YARD SALE, ONLINE</p><h1 id="hero-heading">Good stuff.<br><span>New homes.</span></h1><p class="sign-copy">A warm, useful place for the things you’re ready to pass along.</p><span class="sign-underline" aria-hidden="true"></span></div><span class="sign-fold" aria-hidden="true"></span><span class="sign-edge" aria-hidden="true"></span></article><div class="sign-actions"><a class="button primary" href="/signup">Set up my sale</a><svg class="hero-arrow" viewBox="0 0 150 48" aria-hidden="true" focusable="false"><path d="M4 12c38-12 83-5 124 21"></path><path d="m111 28 20 6-13 13"></path></svg></div></div><aside class="hero-invitation"><span class="invitation-tape" aria-hidden="true"></span><div class="invitation-label">Come on in</div><p class="invitation-copy">The spare chair. The outgrown bike. The box of books by the door.</p><p>Put them in your own little online store. Share the link and arrange a pickup.</p><div class="invitation-actions"><a class="button secondary" href="/marketplace">Have a look around</a><p class="fine-print">You keep the buyer conversation and pickup details.</p></div><div class="price-tag" aria-label="${freeDays} days free"><strong>${freeDays}</strong><span>days free</span></div></aside></div><section class="promise-plank" aria-labelledby="promise-heading"><div><p class="marker-kicker">A fair little promise</p><h2 id="promise-heading">Keep the same little store.</h2></div><p><strong>${freeDays} days free</strong>, then <strong>${formatMoney(priceMinor)}</strong> for each ${paidDays}-day extension. Paid time keeps the same store and listings; one active free store remains visible in your account.</p><p class="plank-note">You arrange pickup and payment with the buyer.</p></section><section class="how-to" aria-labelledby="how-to-heading"><div class="how-to-intro"><p class="marker-kicker">From the spare room to someone else’s</p><h2 id="how-to-heading">Three small steps.</h2><p>No hosting vocabulary required. Just name it, list it, and pass the link along.</p></div><ol class="how-to-list"><li><span class="step-number">01</span><div><h3>Name your sale</h3><p>Choose a name and reserve a public address.</p></div></li><li><span class="step-number">02</span><div><h3>Add your things</h3><p>Put the useful details and photos in one place.</p></div></li><li><span class="step-number">03</span><div><h3>Share your link</h3><p>Talk pickup and payment directly with the buyer.</p></div></li></ol><p class="margin-note" aria-hidden="true">a little room to breathe</p></section></section>`;
  return layout({ title: "Managed storefronts", body });
}

export function signupPage({ errors = [], values = {} } = {}) {
  const body = `<section class="auth-shell"><div class="auth-copy"><div class="eyebrow">Start small</div><h1>Create your seller account.</h1><p class="lede">Create an account, then name your first store. Its free period follows the policy configured by the platform.</p></div><form class="card auth-form" method="post" action="/signup"><h2>Make an account</h2>${errorsBlock(errors)}<label class="field"><span>Email</span><input type="email" name="email" autocomplete="email" value="${escapeHtml(values.email)}" required><small>We’ll use this to sign you in.</small></label><label class="field"><span>Country code <span class="muted">(optional)</span></span><input type="text" name="countryCode" maxlength="2" value="${escapeHtml(values.countryCode)}" placeholder="KH" autocomplete="country"></label><label class="field"><span>Password</span><input type="password" name="password" autocomplete="new-password" minlength="10" required><small>At least 10 characters.</small></label><label class="field"><span>Confirm password</span><input type="password" name="confirmPassword" autocomplete="new-password" minlength="10" required></label><button class="button primary wide" type="submit">Continue to store setup</button><p class="form-foot">Already have an account? <a href="/login">Sign in</a>.</p></form></section>`;
  return layout({ title: "Create account", body });
}

export function loginPage({ errors = [], values = {}, next = "/dashboard" } = {}) {
  const body = `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Welcome back</div><h1>Pick up where you left off.</h1><p class="lede">Your store, your URL, and the work you’ve already put into it are waiting.</p></div><form class="card auth-form" method="post" action="/login"><h2>Sign in</h2>${errorsBlock(errors)}<input type="hidden" name="next" value="${escapeHtml(next)}"><label class="field"><span>Email</span><input type="email" name="email" autocomplete="email" value="${escapeHtml(values.email)}" required></label><label class="field"><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label><button class="button primary wide" type="submit">Sign in</button><p class="form-foot">New here? <a href="/signup">Create an account</a>.</p></form></section>`;
  return layout({ title: "Sign in", body });
}

function storeCard(store, policy) {
  const marketplace = store.state === "running" && !store.marketplace_opted_out && (typeof policy.marketplace_enabled === "boolean" ? policy.marketplace_enabled : store.mode !== "free" && policy.paid_marketplace_enabled);
  const quota = Number(policy.storage_quota_bytes || 0);
  const storage = Number(store.storage_bytes || 0);
  return `<article class="card store-card"><div class="card-top"><div><div class="card-kicker">${escapeHtml(statusLabel(store.mode))} plan</div><h2>${escapeHtml(store.name || store.slug)}</h2></div>${statusBadge(store.state)}</div><p class="domain">${escapeHtml(store.slug)} · ${escapeHtml(store.hostname)}</p><div class="store-meta"><div><span>Current period</span><strong>${escapeHtml(formatDate(store.current_period_ends_at))}</strong></div><div><span>Marketplace</span><strong>${marketplace ? "Eligible" : "Not indexed"}</strong></div><div><span>Storage</span><strong>${storage.toLocaleString()} / ${quota.toLocaleString()} B</strong></div></div><a class="button secondary" href="/stores/${store.id}">View store</a></article>`;
}

export function dashboardPage({ user, stores, policy, csrf, message = "", requireEmailVerification = false }) {
  const activeFree = stores.filter((store) => store.mode === "free" && ["provisioning", "running", "suspended"].includes(store.state)).length;
  const limit = Number(policy.free_active_store_limit) || 1;
  const cards = stores.length ? `<div class="store-grid">${stores.map((store) => storeCard(store, policy)).join("")}</div>` : `<div class="card empty-state"><div class="empty-icon">+</div><h2>A spot for your first sale</h2><p>Give it a name and we’ll reserve a clean public identity for it.</p><a class="button primary" href="/stores/new">Create a store</a></div>`;
  const verification = requireEmailVerification && !user.email_verified_at ? `<div class="alert alert-warning" role="status">Verify ${escapeHtml(user.email)} before creating a hosted store. The development verification link is printed in the server log.<form method="post" action="/account/verification" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button quiet" type="submit">Send another link</button></form></div>` : "";
  const body = `<section class="page-heading"><div><div class="eyebrow">Seller dashboard</div><h1>Your sales.</h1><p class="account-email">${escapeHtml(user.email)}</p><p class="lede">One calm place to keep your storefronts moving.</p></div><div class="button-row"><a class="button secondary" href="/billing">Billing</a><a class="button primary" href="/stores/new">New store</a></div></section>${notice(message)}${verification}<section class="metric-grid"><div class="metric"><span>Stores</span><strong>${stores.length}</strong><small>Hosted in your account</small></div><div class="metric"><span>Free slot</span><strong>${Math.max(0, limit - activeFree)} / ${limit}</strong><small>Active free stores</small></div><div class="metric"><span>Base extension</span><strong>${formatMoney(policy.default_store_price_minor)}</strong><small>For ${policy.default_paid_days} days</small></div></section><div class="section-heading"><div><div class="eyebrow">Your storefronts</div><h2>Keep the link. Keep the work.</h2></div></div>${cards}<form id="csrf-context" hidden><input name="csrf" value="${escapeHtml(csrf)}"></form>`;
  return layout({ title: "Dashboard", body, user: { ...user, csrfToken: csrf } });
}

export function newStorePage({ user, policy, csrf, errors = [], values = {}, baseDomain = "yardsale.local" }) {
  const body = `<section class="page-heading"><div><div class="eyebrow">New sale</div><h1>Choose a name for your sale.</h1><p class="lede">Name it, reserve its public address, and manage the store from your dashboard.</p></div></section><section class="split-layout"><form class="card form-card" method="post" action="/stores"><h2>Store details</h2>${errorsBlock(errors)}<label class="field"><span>Store name</span><input type="text" name="name" maxlength="80" value="${escapeHtml(values.name)}" placeholder="Saturday sale" required><small>This is the name buyers will see.</small></label><label class="field"><span>Public slug</span><input type="text" name="slug" maxlength="48" value="${escapeHtml(values.slug)}" placeholder="saturday-sale"><small>Letters, numbers, and hyphens. Leave blank to derive it from the name.</small></label><label class="field"><span>Coupon <span class="muted">(optional)</span></span><input type="text" name="coupon" maxlength="80" value="${escapeHtml(values.coupon)}" placeholder="PHNOMPENH30"><small>Apply an active campaign coupon after the store is created.</small></label><div class="url-preview"><span>Your reserved address</span><strong>${escapeHtml(values.slug || "your-store")}.${escapeHtml(baseDomain)}</strong></div><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button primary wide" type="submit">Create my store</button><p class="form-foot">${policy.default_free_days} days free under the current platform policy.</p></form><aside class="card side-note"><div class="card-kicker">What happens next</div><ol class="steps"><li><span>01</span><div><strong>Choose a name</strong><p>Pick the name buyers will see.</p></div></li><li><span>02</span><div><strong>Reserve an address</strong><p>We’ll use a unique public slug for your store.</p></div></li><li><span>03</span><div><strong>Manage your store</strong><p>Add listings, check its status, and extend hosted time here.</p></div></li></ol></aside></section>`;
  return layout({ title: "New store", body, user: { ...user, csrfToken: csrf } });
}

function auditLine(event) {
  let metadata = {};
  try { metadata = JSON.parse(event.metadata || "{}"); } catch { /* keep the event readable */ }
  const detail = metadata.grace_ends_at ? ` · grace until ${formatDate(metadata.grace_ends_at)}` : metadata.scheduled_at ? ` · scheduled ${formatDate(metadata.scheduled_at)}` : "";
  return `<div class="timeline-row"><span class="timeline-dot"></span><div><strong>${escapeHtml(statusLabel(event.action.replace("store.", "")))}</strong><span>${escapeHtml(formatDate(event.created_at))}${escapeHtml(detail)}</span></div></div>`;
}

export function storePage({ user, store, policy, audits, entitlements = [], listings = [], csrf, message = "" }) {
  const eligible = store.state === "running" && !store.marketplace_opted_out && (typeof policy.marketplace_enabled === "boolean" ? policy.marketplace_enabled : store.mode !== "free" && policy.paid_marketplace_enabled);
  const expired = ["expired", "deleting"].includes(store.state);
  const deleted = store.state === "deleted";
  const periodCopy = expired ? `Expired ${formatDate(store.current_period_ends_at)}` : `Runs through ${formatDate(store.current_period_ends_at)}`;
  const action = deleted
    ? `<div class="callout"><strong>This store has been deleted.</strong><p>Its hosted data is outside the retention window and this URL cannot be reactivated.</p></div>`
    : expired
    ? `<div class="callout"><strong>Keep this store and its URL.</strong><p>Payment reactivates the same data during the grace window${store.grace_ends_at ? `, which ends ${escapeHtml(formatDate(store.grace_ends_at))}` : ""}.</p><form method="post" action="/stores/${store.id}/checkout"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button primary" type="submit">Extend ${policy.default_paid_days} days · ${formatMoney(policy.default_store_price_minor)}</button></form></div>`
    : `<div class="callout"><strong>Your storefront is ${escapeHtml(statusLabel(store.state))}.</strong><p>The runtime owns the tenant data; the control plane owns its lifecycle, billing, and discovery eligibility.</p><div class="button-row"><form method="post" action="/stores/${store.id}/checkout"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button primary" type="submit">Extend ${policy.default_paid_days} days · ${formatMoney(policy.default_store_price_minor)}</button></form>${store.state === "running" && store.mode !== "free" ? `<form method="post" action="/stores/${store.id}/promotions"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="promotionType" value="feature_store"><button class="button secondary" type="submit">Feature store · ${formatMoney(policy.promotion_feature_store_price_minor)}</button></form>${listings.length ? `<form method="post" action="/stores/${store.id}/promotions"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="promotionType" value="feature_listing"><select name="listingId" aria-label="Listing to feature" required><option value="">Choose listing</option>${listings.map((listing) => `<option value="${listing.id}">${escapeHtml(listing.title)}</option>`).join("")}</select><button class="button secondary" type="submit">Feature listing · ${formatMoney(policy.promotion_feature_listing_price_minor)}</button></form>` : ""}` : ""}</div></div>`;
  const coupon = `<section class="card inline-card"><div><div class="eyebrow">Entitlements</div><h2>Have a coupon?</h2><p class="muted">Apply an operator-issued code to this store.</p></div><form method="post" action="/stores/${store.id}/coupon" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input name="code" aria-label="Coupon code" placeholder="PHNOMPENH30" maxlength="80" required><button class="button secondary" type="submit">Apply</button></form></section>`;
  const deleteAction = deleted ? "" : `<form method="post" action="/stores/${store.id}/delete" class="danger-zone"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="confirm" value="DELETE"><button class="button quiet" type="submit">Delete this store</button><small>This removes its runtime data and cannot be undone.</small></form>`;
  const marketplaceAction = deleted ? `<p class="muted">Marketplace discovery is unavailable for deleted stores.</p>` : (!eligible && store.mode === "free" && policy.marketplace_enabled !== true ? `<p class="muted">Marketplace discovery unlocks after a paid extension.</p>` : `<form method="post" action="/stores/${store.id}/marketplace" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="enabled" value="${store.marketplace_opted_out ? "1" : "0"}"><button class="button secondary" type="submit">${store.marketplace_opted_out ? "Enable indexing" : "Disable indexing"}</button></form>`);
  const entitlementRows = entitlements.slice(0, 8).map((entitlement) => `<div class="admin-store-row"><div><strong>${escapeHtml(entitlement.key)}</strong><span>${escapeHtml(entitlement.source)} · ${escapeHtml(entitlement.value)} · ${escapeHtml(entitlement.reason || "No note")}</span></div></div>`).join("");
  const body = `<section class="page-heading"><div><a class="back-link" href="/dashboard">← Dashboard</a><div class="eyebrow">Hosted store</div><h1>${escapeHtml(store.name || store.slug)}</h1><p class="domain">${escapeHtml(store.slug)} · ${escapeHtml(store.hostname)}</p></div>${statusBadge(store.state)}</section>${notice(message)}${action}<section class="metric-grid"><div class="metric"><span>Plan</span><strong>${escapeHtml(statusLabel(store.mode))}</strong><small>${escapeHtml(periodCopy)}</small></div><div class="metric"><span>Marketplace</span><strong>${eligible ? "Eligible" : "Private"}</strong><small>${eligible ? "Paid discovery is enabled" : "Free stores are not indexed"}</small></div><div class="metric"><span>Runtime</span><strong>${escapeHtml(store.runtime_instance_id ? store.runtime_instance_id.split(":")[0] : "waiting")}</strong><small>${Number(store.runtime_port || 0) ? `Port ${store.runtime_port}` : "Pending assignment"}</small></div></section><section class="split-layout detail-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Lifecycle</div><h2>What the control plane knows</h2></div></div><div class="timeline">${audits.length ? audits.map(auditLine).join("") : `<p class="muted">The first lifecycle event will appear here.</p>`}</div></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Commercial policy</div><h2>Current defaults</h2></div></div><dl class="definition-list"><div><dt>Free period</dt><dd>${policy.default_free_days} days</dd></div><div><dt>Paid extension</dt><dd>${formatMoney(policy.default_store_price_minor)} / ${policy.default_paid_days} days</dd></div><div><dt>Grace window</dt><dd>${policy.default_grace_days} days</dd></div><div><dt>Storage tracked</dt><dd>${Number(store.storage_bytes || 0).toLocaleString()} / ${Number(policy.storage_quota_bytes || 0).toLocaleString()} bytes</dd></div><div><dt>Provision attempts</dt><dd>${Number(store.provision_attempts || 0)}</dd></div>${store.last_provision_error ? `<div><dt>Last runtime error</dt><dd>${escapeHtml(store.last_provision_error)}</dd></div>` : ""}</dl></div></section><section class="card inline-card"><div><div class="eyebrow">Marketplace</div><h2>Local discovery</h2><p class="muted">${eligible ? "Your public listings can appear in nearby search." : "Marketplace eligibility follows your paid plan and current policy."}</p></div>${marketplaceAction}</section>${entitlements.length ? `<section class="card detail-card"><div class="section-heading compact-heading"><div><div class="eyebrow">Entitlements</div><h2>Why this store has access</h2></div></div><div class="admin-store-list">${entitlementRows}</div></section>` : ""}${coupon}${deleteAction}<form method="post" action="/logout" class="mobile-signout"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button quiet" type="submit">Sign out</button></form>`;
  return layout({ title: store.slug, body, user: { ...user, csrfToken: csrf } });
}

function policyRow(policy) {
  return `<div class="policy-row"><div><code>${escapeHtml(policy.key)}</code><span>Updated ${escapeHtml(formatDate(policy.updated_at))} by ${escapeHtml(policy.updated_by)}</span></div><form method="post" action="/admin/policies" class="policy-form"><input type="hidden" name="csrf" value="__CSRF__"><input type="hidden" name="key" value="${escapeHtml(policy.key)}"><input name="value" value="${escapeHtml(policy.value)}" aria-label="${escapeHtml(policy.key)}"><button class="button secondary" type="submit">Save</button></form></div>`;
}

export function adminPage({ user, policies, stores, campaigns = [], coupons = [], reports = [], blocklist = [], backups = [], metrics = {}, hosts = [], users = [], userQuery = "", csrf, message = "", errors = [] }) {
  const rows = policies.map((policy) => policyRow(policy).replaceAll("__CSRF__", escapeHtml(csrf))).join("");
  const storeRows = stores.length ? stores.map((store) => {
    const toggle = store.state === "suspended" ? "resume" : "suspend";
    const toggleLabel = store.state === "suspended" ? "Resume" : "Suspend";
    return `<div class="admin-store-row"><div><strong>${escapeHtml(store.name || store.slug)}</strong><span>${escapeHtml(store.slug)} · ${escapeHtml(store.owner_email)} · ${escapeHtml(statusLabel(store.mode))} · ${escapeHtml(statusLabel(store.state))}</span></div><div class="button-row"><form method="post" action="/admin/stores/${store.id}/action"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="action" value="${toggle}"><button class="button secondary" type="submit">${toggleLabel}</button></form><form method="post" action="/admin/stores/${store.id}/action"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="action" value="comp"><input type="hidden" name="days" value="30"><button class="button secondary" type="submit">Comp 30d</button></form><form method="post" action="/admin/stores/${store.id}/action"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="action" value="${store.marketplace_opted_out ? "index" : "deindex"}"><button class="button secondary" type="submit">${store.marketplace_opted_out ? "Index" : "De-index"}</button></form></div></div>`;
  }).join("") : `<p class="muted">No stores yet.</p>`;
  const campaignRows = campaigns.length ? campaigns.map((campaign) => `<div class="admin-store-row"><div><strong>${escapeHtml(campaign.name)}</strong><span>${escapeHtml(campaign.status)} · ${escapeHtml(formatDate(campaign.starts_at))} → ${escapeHtml(formatDate(campaign.ends_at))}</span></div><form method="post" action="/admin/campaigns/status"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="id" value="${campaign.id}"><input type="hidden" name="status" value="${campaign.status === "active" ? "paused" : "active"}"><button class="button secondary" type="submit">${campaign.status === "active" ? "Pause" : "Activate"}</button></form></div>`).join("") : `<p class="muted">No campaigns yet.</p>`;
  const couponRows = coupons.length ? coupons.map((coupon) => `<div class="admin-store-row"><div><strong>${escapeHtml(coupon.code)}</strong><span>${escapeHtml(coupon.status)} · ${escapeHtml(formatDate(coupon.starts_at))} → ${escapeHtml(formatDate(coupon.ends_at))}</span></div><form method="post" action="/admin/coupons/status"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="id" value="${coupon.id}"><input type="hidden" name="status" value="${coupon.status === "active" ? "paused" : "active"}"><button class="button secondary" type="submit">${coupon.status === "active" ? "Pause" : "Activate"}</button></form></div>`).join("") : `<p class="muted">No coupons yet.</p>`;
  const reportRows = reports.length ? reports.map((report) => `<div class="report-row"><div><strong>${escapeHtml(report.title || "Removed listing")}</strong><span>${escapeHtml(report.reason)} · ${escapeHtml(report.reporter_email || "anonymous")} · ${escapeHtml(formatDate(report.created_at))}</span><p>${escapeHtml(report.details)}</p></div><div class="button-row"><form method="post" action="/admin/reports/${report.id}"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="status" value="dismissed"><button class="button secondary" type="submit">Dismiss</button></form><form method="post" action="/admin/reports/${report.id}"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="status" value="resolved"><input type="hidden" name="blockListing" value="1"><button class="button secondary" type="submit">Block listing</button></form></div></div>`).join("") : `<p class="muted">No open reports.</p>`;
  const blocklistRows = blocklist.length ? `<div class="admin-store-list">${blocklist.map((entry) => `<div class="admin-store-row"><span class="tag">${escapeHtml(entry.kind)}: ${escapeHtml(entry.value)}</span><form method="post" action="/admin/blocklist/${entry.id}/remove" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button quiet" type="submit">Remove</button></form></div>`).join("")}</div>` : `<p class="muted">No blocklist entries.</p>`;
  const backupRows = backups.length ? backups.slice(0, 5).map((backup) => `<div class="admin-store-row"><div><strong>${escapeHtml(backup.name)}</strong><span>${escapeHtml(formatDate(backup.created_at))}</span></div></div>`).join("") : `<p class="muted">No local backups yet.</p>`;
  const hostRows = hosts.length ? hosts.map((host) => `<div class="admin-store-row"><div><strong>${escapeHtml(host.hostname)}</strong><span>${escapeHtml(host.region)} · ${escapeHtml(host.status)} · ${host.instance_count} instances</span></div></div>`).join("") : `<p class="muted">No deployment hosts.</p>`;
  const userRows = users.length ? users.slice(0, 8).map((entry) => `<div class="admin-store-row"><div><strong>${escapeHtml(entry.email)}</strong><span>${entry.is_admin ? "operator" : "seller"} · joined ${escapeHtml(formatDate(entry.created_at))}</span></div></div>`).join("") : `<p class="muted">No users.</p>`;
  const expiryExtension = `<section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Retention</div><h2>Set an explicit expiry</h2></div></div><form class="admin-create-form" method="post" action="/admin/expiry"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><select name="storeId" aria-label="Store" required><option value="">Choose store</option>${stores.map((store) => `<option value="${store.id}">${escapeHtml(store.slug)}</option>`).join("")}</select><input type="datetime-local" name="endsAt" aria-label="Expiry end date and time" required><select name="mode" aria-label="Expiry mode"><option value="comped">Comped</option><option value="paid">Paid</option></select><input name="reason" aria-label="Reason or support note" placeholder="Reason / support note"><button class="button secondary" type="submit">Save expiry</button></form></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Policy note</div><h2>Every override is audited</h2></div></div><p class="muted">Manual time, marketplace access, quota changes, host moves, and account actions remain visible in the audit trail for support and reconciliation.</p></div></section>`;
  const hostOptions = hosts.filter((host) => host.status === "ready").map((host) => `<option value="${host.id}">${escapeHtml(host.hostname)} · ${escapeHtml(host.region)}</option>`).join("");
  const retryRows = stores.filter((store) => ["failed", "provisioning"].includes(store.state)).map((store) => `<form method="post" action="/admin/stores/${store.id}/action" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="action" value="retry"><button class="button secondary" type="submit">Retry ${escapeHtml(store.slug)}</button></form>`).join("");
  const userActions = users.slice(0, 20).map((entry) => `<div class="admin-store-row"><div><strong>${escapeHtml(entry.email)}</strong><span>${entry.is_admin ? "operator" : "seller"} · ${escapeHtml(entry.status)}</span></div>${entry.id === user.id ? `<span class="muted">Current operator</span>` : `<form method="post" action="/admin/users/${entry.id}/action" class="inline-form"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input type="hidden" name="action" value="${entry.status === "suspended" ? "resume" : "suspend"}"><button class="button secondary" type="submit">${entry.status === "suspended" ? "Resume" : "Suspend"}</button></form>`}</div>`).join("");
  const adminExtensions = `<section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Manual controls</div><h2>Entitlements and moves</h2></div></div><form class="admin-create-form" method="post" action="/admin/entitlements"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><select name="storeId" aria-label="Store" required><option value="">Choose store</option>${stores.map((store) => `<option value="${store.id}">${escapeHtml(store.slug)}</option>`).join("")}</select><select name="key" aria-label="Entitlement key"><option value="period_extension_days">Hosted days</option><option value="marketplace_enabled">Marketplace access</option><option value="storage_quota_bytes">Storage quota bytes</option><option value="listing_limit">Listing limit</option></select><input name="value" aria-label="Entitlement value" placeholder="30 or true" required><div class="form-grid"><select name="source" aria-label="Entitlement source"><option value="admin_comp">Admin comp</option><option value="manual_override">Manual override</option></select><select name="mode" aria-label="Entitlement mode"><option value="comped">Comped</option><option value="paid">Paid</option></select></div><input type="datetime-local" name="endsAt" aria-label="Entitlement end date and time"><input name="reason" aria-label="Reason or support note" placeholder="Reason / support note"><button class="button secondary" type="submit">Grant entitlement</button></form><div class="button-row">${retryRows}</div>${stores.filter((store) => hostOptions && hosts.length > 1).map((store) => `<form method="post" action="/admin/stores/${store.id}/migrate" class="admin-create-form"><label>Move ${escapeHtml(store.slug)}<select name="destinationHostId" required><option value="">Destination host</option>${hostOptions}</select></label><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button secondary" type="submit">Migrate store</button></form>`).join("")}</div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Account controls</div><h2>Search users</h2></div></div><form class="admin-create-form" method="get" action="/admin"><input name="user_q" aria-label="Search users" value="${escapeHtml(userQuery)}" placeholder="seller@example.com"><button class="button secondary" type="submit">Search</button></form><div class="admin-store-list">${userActions || `<p class="muted">No matching users.</p>`}</div></div></section><section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Campaign rules</div><h2>Targeted launch controls</h2></div></div><form class="admin-create-form" method="post" action="/admin/campaigns"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input name="name" aria-label="Campaign name" placeholder="Cambodia launch" required><div class="form-grid"><input type="datetime-local" name="startsAt" aria-label="Campaign start date and time" required><input type="datetime-local" name="endsAt" aria-label="Campaign end date and time" required></div><div class="form-grid"><input type="number" name="freeDays" aria-label="Campaign free days" min="1" max="3650" placeholder="Free days"><input type="number" name="paidDays" aria-label="Campaign paid days" min="1" max="3650" placeholder="Paid days"></div><div class="form-grid"><input type="number" name="priceMinor" aria-label="Campaign price in minor units" min="0" placeholder="Price minor"><select name="marketplace" aria-label="Campaign marketplace setting"><option value="">Marketplace default</option><option value="true">Enable marketplace</option><option value="false">Disable marketplace</option></select></div><input name="eligibilityRule" aria-label="Campaign eligibility rule" placeholder='{"country_code":"KH"}'><input name="storageQuota" aria-label="Campaign storage quota bytes" type="number" min="0" placeholder="Storage quota bytes"><input name="listingLimit" aria-label="Campaign listing limit" type="number" min="1" placeholder="Listing limit"><button class="button secondary" type="submit">Create targeted campaign</button></form></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Coupon payload</div><h2>Reusable entitlements</h2></div></div><form class="admin-create-form" method="post" action="/admin/coupons"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input name="code" aria-label="Coupon code" placeholder="PHNOMPENH30" required><div class="form-grid"><input type="datetime-local" name="startsAt" aria-label="Coupon start date and time" required><input type="datetime-local" name="endsAt" aria-label="Coupon end date and time" required></div><div class="form-grid"><input type="number" name="maxRedemptions" aria-label="Coupon maximum redemptions" min="1" placeholder="Max redemptions"><input type="number" name="perAccountLimit" aria-label="Coupon per-account limit" min="1" value="1" placeholder="Per-account limit"></div><input name="payloadJson" aria-label="Coupon payload JSON" placeholder='{"period_extension_days":30,"marketplace_enabled":true}'><input name="eligibilityRule" aria-label="Coupon eligibility rule" placeholder='{"email_domain":"example.com"}'><button class="button secondary" type="submit">Create entitlement coupon</button></form></div></section>`;
  const body = `<section class="page-heading"><div><div class="eyebrow">Operations</div><h1>Control plane admin.</h1><p class="lede">Change policy without a redeploy, then see the audit trail in the store view.</p></div></section>${notice(message)}${errorsBlock(errors)}<section class="metric-grid admin-metrics"><div class="metric"><span>Stores</span><strong>${metrics.stores || 0}</strong><small>${metrics.storesByState?.running || 0} running</small></div><div class="metric"><span>Indexed</span><strong>${metrics.indexedListings || 0}</strong><small>${metrics.openReports || 0} open reports</small></div><div class="metric"><span>Storage</span><strong>${Number(metrics.storageBytes || 0).toLocaleString()}</strong><small>tracked bytes</small></div></section><section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Platform policy</div><h2>Defaults are data</h2></div></div><div class="policy-list">${rows}</div></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Hosted stores</div><h2>Runtime actions</h2></div></div><div class="admin-store-list">${storeRows}</div></div></section><section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Campaigns</div><h2>Scheduled offers</h2></div></div><div class="admin-store-list">${campaignRows}</div><form class="admin-create-form" method="post" action="/admin/campaigns"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input name="name" aria-label="Campaign name" placeholder="Launch Month" required><div class="form-grid"><input type="datetime-local" name="startsAt" aria-label="Campaign start date and time" required><input type="datetime-local" name="endsAt" aria-label="Campaign end date and time" required></div><div class="form-grid"><input type="number" name="freeDays" aria-label="Campaign free days" min="1" max="3650" placeholder="Free days"><input type="number" name="priceMinor" aria-label="Campaign price in minor units" min="0" placeholder="Price minor units"></div><button class="button secondary" type="submit">Create campaign</button></form></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Coupons</div><h2>Entitlement codes</h2></div></div><div class="admin-store-list">${couponRows}</div><form class="admin-create-form" method="post" action="/admin/coupons"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input name="code" aria-label="Coupon code" placeholder="PHNOMPENH30" required><div class="form-grid"><input type="datetime-local" name="startsAt" aria-label="Coupon start date and time" required><input type="datetime-local" name="endsAt" aria-label="Coupon end date and time" required></div><div class="form-grid"><input type="number" name="freeDays" aria-label="Coupon free days" min="1" placeholder="Free days"><input type="number" name="maxRedemptions" aria-label="Coupon maximum redemptions" min="1" placeholder="Max redemptions"></div><button class="button secondary" type="submit">Create coupon</button></form></div></section><section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Moderation</div><h2>Open reports</h2></div></div><div class="report-list">${reportRows}</div></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Blocklist</div><h2>Keep the marketplace clean</h2></div></div>${blocklistRows}<form class="admin-create-form" method="post" action="/admin/blocklist"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><div class="form-grid"><select name="kind" aria-label="Blocklist entry type"><option value="phrase">Phrase</option><option value="email">Email</option><option value="domain">Domain</option><option value="ip">IP</option></select><input name="value" aria-label="Blocklist value" placeholder="phrase or address" required></div><input name="reason" aria-label="Blocklist reason" placeholder="Reason"><button class="button secondary" type="submit">Add blocklist entry</button></form></div></section><section class="split-layout admin-layout"><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Operations</div><h2>Backups and releases</h2></div></div><div class="button-row"><form method="post" action="/admin/backup"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button secondary" type="submit">Create backup</button></form><form method="post" action="/admin/search/reconcile"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button secondary" type="submit">Reconcile search</button></form></div><form class="admin-create-form" method="post" action="/admin/upgrade"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><input name="imageVersion" aria-label="Runtime image version" placeholder="yardsale:1.0.1" required><button class="button secondary" type="submit">Upgrade running stores</button></form><div class="admin-store-list">${backupRows}</div></div><div class="card"><div class="section-heading compact-heading"><div><div class="eyebrow">Capacity</div><h2>Host and account inventory</h2></div></div><div class="admin-store-list">${hostRows}${userRows}</div></div></section>`;
  return layout({ title: "Admin", body: body + adminExtensions + expiryExtension, user: { ...user, csrfToken: csrf } });
}

export function billingPage({ user, payments, csrf, message = "" }) {
  const rows = payments.length ? payments.map((payment) => `<div class="admin-store-row"><div><strong>${escapeHtml(payment.kind.replaceAll("_", " "))}</strong><span>${escapeHtml(payment.store_name || "Store")} · ${escapeHtml(payment.provider)} · ${escapeHtml(payment.status)} · ${escapeHtml(formatDate(payment.created_at))}</span></div><strong>${formatMoney(payment.amount_minor, payment.currency)}</strong></div>`).join("") : `<div class="empty-state"><h2>No payments yet</h2><p>Paid extensions and promotions will appear here.</p></div>`;
  const body = `<section class="page-heading"><div><div class="eyebrow">Account</div><h1>Billing history.</h1><p class="lede">A clear record of hosted time and sponsored placement.</p></div><a class="button secondary" href="/dashboard">Back to dashboard</a></section>${notice(message)}<section class="card billing-list">${rows}</section><form method="post" action="/logout" class="mobile-signout"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button quiet" type="submit">Sign out</button></form>`;
  return layout({ title: "Billing", body, user: { ...user, csrfToken: csrf } });
}

export function mockCheckoutPage({ user, payment, csrf, error = "" }) {
  const metadata = (() => { try { return JSON.parse(payment.metadata || "{}"); } catch { return {}; } })();
  const label = payment.kind === "promotion" ? `${String(metadata.promotion_type || "promotion").replaceAll("_", " ")} placement` : `${payment.entitlement_days} days of hosted time`;
  const body = `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Mock checkout</div><h1>Confirm the next useful thing.</h1><p class="lede">This local provider stands in for the payment gateway while the billing integration is being validated.</p></div><div class="card auth-form"><h2>${escapeHtml(label)}</h2>${error ? errorsBlock([error]) : ""}<div class="checkout-total"><span>Total</span><strong>${formatMoney(payment.amount_minor, payment.currency)}</strong></div><p class="muted">Payment reference: ${escapeHtml(payment.provider_reference)}</p><form method="post" action="/billing/mock/${payment.id}"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><button class="button primary wide" type="submit">Complete mock payment</button></form><a class="button quiet wide" href="/billing">Cancel</a></div></section>`;
  return layout({ title: "Checkout", body, user: { ...user, csrfToken: csrf } });
}

export function paywayCheckoutPage({ user, payment, checkout, csrf = "" }) {
  const fields = Object.entries(checkout?.fields || {}).map(([key, value]) => `<input type="hidden" name="${escapeHtml(key)}" value="${escapeHtml(value)}">`).join("");
  const action = safeUrl(checkout?.action);
  const body = `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">ABA PayWay</div><h1>Continue to secure checkout.</h1><p class="lede">You’ll complete this ${payment.kind === "promotion" ? "promotion" : "hosted-time"} payment on ABA PayWay, then return to YardSale Cloud.</p></div><div class="card auth-form"><div class="checkout-total"><span>Total</span><strong>${formatMoney(payment.amount_minor, payment.currency)}</strong></div><p class="muted">Payment reference: ${escapeHtml(payment.provider_reference)}</p><form method="post" action="${escapeHtml(action)}">${fields}<button class="button primary wide" type="submit">Continue to ABA PayWay</button></form><a class="button quiet wide" href="/billing">Cancel</a><p class="fine-print">If the gateway rejects this request, confirm the merchant profile, whitelisted return URL, and sandbox/production base URL.</p></div></section>`;
  return layout({ title: "ABA PayWay checkout", body, user: { ...user, csrfToken: csrf } });
}

function marketplaceCard(listing) {
  const image = listing.thumbnail_url && safeUrl(listing.thumbnail_url) !== "#" ? `<img src="${escapeHtml(safeUrl(listing.thumbnail_url))}" alt="" loading="lazy">` : `<div class="listing-image-placeholder">YS</div>`;
  const destination = `/marketplace/click/${listing.id}`;
  const sponsor = Number(listing.promotion_score || 0) > 0 ? `<span class="sponsored-label">Sponsored</span>` : "";
  return `<article class="card listing-card"><div class="listing-image">${image}</div><div class="listing-body"><div class="card-kicker">${escapeHtml(listing.city || listing.display_location || "Local pickup")} ${sponsor}</div><h2>${escapeHtml(listing.title)}</h2><strong class="listing-price">${formatMoney(listing.price_minor, listing.currency)}</strong><p>${escapeHtml(listing.description_excerpt)}</p><div class="listing-foot"><a href="${destination}">View listing ↗</a><span><a href="/marketplace/report?listing=${listing.id}">Report item</a> · <a href="/marketplace/report-store?store=${listing.store_id}">Report store</a></span></div></div></article>`;
}

export function marketplacePage({ results, filters = {}, countries = [], cities = [], areas = [], categories = [], conditions = [], currencies = [] }) {
  const options = (values, selected) => values.map((value) => `<option value="${escapeHtml(value)}" ${value === selected ? "selected" : ""}>${escapeHtml(value)}</option>`).join("");
  const filter = (label, control) => `<label class="field filter-field"><span>${label}</span>${control}</label>`;
  const selectFilter = (name, label, emptyLabel, values, selected) => filter(label, `<select name="${name}"><option value="">${emptyLabel}</option>${options(values, selected)}</select>`);
  const body = `<section class="marketplace-hero"><div><div class="eyebrow">Local marketplace</div><h1>Have a look around.</h1><p class="lede">Search public listings from stores that opted into YardSale discovery.</p></div></section><form class="card search-panel" method="get" action="/marketplace">${filter("Search listings", `<input class="search-input" name="q" value="${escapeHtml(filters.q)}" placeholder="Search lamps, bikes, furniture…">`)}<div class="form-grid">${selectFilter("country", "Country", "Any country", countries, filters.country)}${selectFilter("city", "City", "Any city", cities, filters.city)}${selectFilter("area", "Area", "Any area", areas, filters.area)}${selectFilter("category", "Category", "Any category", categories, filters.category)}${selectFilter("condition", "Condition", "Any condition", conditions, filters.condition)}${selectFilter("currency", "Currency", "Any currency", currencies, filters.currency)}${filter("Minimum price", `<input type="number" name="min" min="0" step="0.01" value="${escapeHtml(filters.min)}" placeholder="0.00">`)}${filter("Maximum price", `<input type="number" name="max" min="0" step="0.01" value="${escapeHtml(filters.max)}" placeholder="0.00">`)}${filter("Sort by", `<select name="sort"><option value="relevance" ${filters.sort === "relevance" ? "selected" : ""}>Relevance</option><option value="newest" ${filters.sort === "newest" ? "selected" : ""}>Newest</option><option value="price-asc" ${filters.sort === "price-asc" ? "selected" : ""}>Lowest price</option><option value="price-desc" ${filters.sort === "price-desc" ? "selected" : ""}>Highest price</option></select>`)}</div><button class="button primary" type="submit">Search marketplace</button></form><div class="section-heading marketplace-heading"><div><div class="eyebrow">${results.length} results</div><h2>Find a new home for it.</h2></div></div>${results.length ? `<div class="listing-grid">${results.map(marketplaceCard).join("")}</div>` : `<div class="card empty-state"><h2>No public listings match that yet.</h2><p>Try a broader search or check back as more local stores opt in.</p></div>`}`;
  return layout({ title: "Marketplace", body });
}

export function reportPage({ listing, csrf = "", errors = [], submitted = false }) {
  const body = submitted ? `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Thank you</div><h1>Report received.</h1><p class="lede">We’ll review the listing against the marketplace rules.</p><a class="button primary" href="/marketplace">Back to marketplace</a></div></section>` : `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Marketplace safety</div><h1>Something wrong with this listing?</h1><p class="lede">Send a short report and the operator queue will take a look.</p></div><form class="card auth-form" method="post" action="/marketplace/report?listing=${encodeURIComponent(listing?.id || "")}"><h2>${escapeHtml(listing?.title || "Listing")}</h2>${errorsBlock(errors)}<input type="hidden" name="listingId" value="${escapeHtml(listing?.id)}"><input type="hidden" name="csrf" value="${escapeHtml(csrf)}"><label class="field"><span>Reason</span><select name="reason" required><option value="">Choose one</option><option value="prohibited_item">Prohibited item</option><option value="spam">Spam</option><option value="misleading">Misleading</option><option value="copyright">Copyright</option><option value="other">Other</option></select></label><label class="field"><span>Your email <span class="muted">(optional)</span></span><input type="email" name="reporterEmail" autocomplete="email"></label><label class="field"><span>Details</span><textarea name="details" rows="5" maxlength="2000" placeholder="What should we know?"></textarea></label><button class="button primary wide" type="submit">Submit report</button></form></section>`;
  return layout({ title: "Report listing", body });
}

export function storeReportPage({ store, errors = [], submitted = false }) {
  const body = submitted ? `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Thank you</div><h1>Report received.</h1><p class="lede">We’ll review the store against the marketplace rules.</p><a class="button primary" href="/marketplace">Back to marketplace</a></div></section>` : `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Marketplace safety</div><h1>Report this store.</h1><p class="lede">Send a short report and the operator queue will take a look.</p></div><form class="card auth-form" method="post" action="/marketplace/report-store?store=${encodeURIComponent(store?.id || "")}"><h2>${escapeHtml(store?.name || store?.slug || "Store")}</h2>${errorsBlock(errors)}<label class="field"><span>Reason</span><select name="reason" required><option value="">Choose one</option><option value="prohibited_item">Prohibited item</option><option value="spam">Spam</option><option value="misleading">Misleading</option><option value="copyright">Copyright</option><option value="other">Other</option></select></label><label class="field"><span>Your email <span class="muted">(optional)</span></span><input type="email" name="reporterEmail" autocomplete="email"></label><label class="field"><span>Details</span><textarea name="details" rows="5" maxlength="2000"></textarea></label><button class="button primary wide" type="submit">Submit report</button></form></section>`;
  return layout({ title: "Report store", body });
}

export function verificationPage({ verified, email = "" }) {
  const body = `<section class="auth-shell compact"><div class="auth-copy"><div class="eyebrow">Account security</div><h1>${verified ? "Email verified." : "That link is no longer valid."}</h1><p class="lede">${verified ? `Thanks — ${escapeHtml(email)} can now use the account’s hosted-store features.` : "Request a fresh verification link from the account flow."}</p><a class="button primary" href="${verified ? "/dashboard" : "/"}">${verified ? "Open dashboard" : "Back to YardSale Cloud"}</a></div></section>`;
  return layout({ title: verified ? "Email verified" : "Verification failed", body });
}

export function legalPage(title, heading, paragraphs) {
  const body = `<section class="legal-page"><div class="eyebrow">YardSale Cloud</div><h1>${escapeHtml(heading)}</h1>${paragraphs.map((paragraph) => `<p>${escapeHtml(paragraph)}</p>`).join("")}</section>`;
  return layout({ title, body });
}

export function errorPage(title, message, status = 500) {
  const body = `<section class="auth-shell compact"><div class="eyebrow">${status}</div><h1>${escapeHtml(title)}</h1><p class="lede">${escapeHtml(message)}</p><a class="button primary" href="/">Back to YardSale Cloud</a></section>`;
  return { html: layout({ title, body }), status };
}
